def _qlike_loss(pred: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
    """QLIKE in log-RV space: exp(y - y_hat) - (y - y_hat) - 1."""
    diff = target - pred
    diff = torch.clamp(diff, min=-10.0, max=10.0)
    return torch.mean(torch.exp(diff) - diff - 1.0)

